-- CounterNest POS Phase 33.9: internal production release-candidate gate and sign-off.
create table public.internal_release_candidate_runs(
  id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,release_version text not null,phase text not null,
  status text not null check(status in('passed','warning','failed','approved')),checks jsonb not null,run_note text,run_by uuid not null references auth.users(id) on delete restrict,run_at timestamptz not null default now(),
  approved_by uuid references auth.users(id) on delete restrict,approved_at timestamptz,approval_note text
);
create table public.internal_release_candidate_events(
  id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,run_id uuid not null references public.internal_release_candidate_runs(id) on delete restrict,
  action text not null,note text,details jsonb not null default '{}'::jsonb,performed_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now()
);
create index internal_release_candidate_runs_idx on public.internal_release_candidate_runs(shop_id,run_at desc);
alter table public.internal_release_candidate_runs enable row level security;alter table public.internal_release_candidate_events enable row level security;
create policy release_candidate_admin_read on public.internal_release_candidate_runs for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());
create policy release_candidate_events_admin_read on public.internal_release_candidate_events for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

create or replace function public.run_internal_release_candidate(p_note text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();v_checks jsonb;v_status text;v_id uuid;v_admins integer;v_critical integer;v_overdue integer;v_stale_cash integer;v_security text;v_recovery text;v_backup_age integer;v_backup_target integer;
begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;
select count(*) into v_admins from public.staff_profiles where shop_id=v_shop and role='admin' and active;select count(*) into v_critical from public.operational_alerts where shop_id=v_shop and severity='critical' and status<>'resolved';select count(*) into v_overdue from public.operational_tasks where shop_id=v_shop and status in('open','accepted') and due_at<now();select count(*) into v_stale_cash from public.cash_drawer_sessions where shop_id=v_shop and status='open' and opened_at<now()-interval '24 hours';select status into v_security from public.security_review_runs where shop_id=v_shop order by run_at desc limit 1;select result into v_recovery from public.recovery_drill_records where shop_id=v_shop order by drill_date desc,created_at desc limit 1;select coalesce(current_date-max(requested_at::date),9999) into v_backup_age from public.backup_exports where shop_id=v_shop;select coalesce(backup_target_days,7) into v_backup_target from public.security_retention_settings where shop_id=v_shop;
v_checks:=jsonb_build_array(
 jsonb_build_object('key','administrator','label','Active administrator exists','required',true,'status',case when v_admins>0 then 'passed' else 'failed' end,'detail',v_admins||' active administrator(s)'),
 jsonb_build_object('key','critical_alerts','label','No unresolved critical alerts','required',true,'status',case when v_critical=0 then 'passed' else 'failed' end,'detail',v_critical||' unresolved critical alert(s)'),
 jsonb_build_object('key','stale_cash','label','No Daily Cash record open over 24 hours','required',true,'status',case when v_stale_cash=0 then 'passed' else 'failed' end,'detail',v_stale_cash||' stale cash record(s)'),
 jsonb_build_object('key','security_review','label','Latest security review passed','required',true,'status',case when v_security='passed' then 'passed' when v_security is null then 'failed' else 'warning' end,'detail',coalesce(v_security,'No review recorded')),
 jsonb_build_object('key','recovery_drill','label','Recovery drill passed in a test environment','required',true,'status',case when v_recovery='passed' then 'passed' when v_recovery is null then 'failed' else 'warning' end,'detail',coalesce(v_recovery,'No drill recorded')),
 jsonb_build_object('key','recent_backup','label','Business backup is within target','required',true,'status',case when v_backup_age<=v_backup_target then 'passed' else 'failed' end,'detail',case when v_backup_age=9999 then 'No backup recorded' else v_backup_age||' day(s) since export' end),
 jsonb_build_object('key','overdue_tasks','label','No overdue operational tasks','required',false,'status',case when v_overdue=0 then 'passed' else 'warning' end,'detail',v_overdue||' overdue task(s)')
);
v_status:=case when v_checks@>'[{"status":"failed"}]'::jsonb then 'failed' when v_checks@>'[{"status":"warning"}]'::jsonb then 'warning' else 'passed' end;
insert into public.internal_release_candidate_runs(shop_id,release_version,phase,status,checks,run_note,run_by) values(v_shop,'1.22.0','33.9',v_status,v_checks,nullif(trim(p_note),''),auth.uid()) returning id into v_id;insert into public.internal_release_candidate_events(shop_id,run_id,action,note,details,performed_by) values(v_shop,v_id,'run_completed',nullif(trim(p_note),''),jsonb_build_object('status',v_status),auth.uid());return jsonb_build_object('id',v_id,'release_version','1.22.0','phase','33.9','status',v_status,'checks',v_checks,'run_at',now());end $$;

create or replace function public.approve_internal_release_candidate(p_run_id uuid,p_note text) returns void language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_row public.internal_release_candidate_runs%rowtype;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if length(trim(coalesce(p_note,'')))<10 then raise exception 'Approval note must contain at least 10 characters';end if;select * into v_row from public.internal_release_candidate_runs where id=p_run_id and shop_id=v_shop for update;if v_row.id is null then raise exception 'Release-candidate run not found';end if;if v_row.status<>'passed' then raise exception 'Only a fully passed release-candidate run can be approved';end if;update public.internal_release_candidate_runs set status='approved',approved_by=auth.uid(),approved_at=now(),approval_note=trim(p_note) where id=v_row.id;insert into public.internal_release_candidate_events(shop_id,run_id,action,note,details,performed_by) values(v_shop,v_row.id,'approved',trim(p_note),jsonb_build_object('release_version',v_row.release_version),auth.uid());end $$;

create or replace function public.get_internal_release_candidate_board() returns jsonb language plpgsql security definer stable set search_path=public as $$declare v_shop uuid:=public.current_shop_id();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;return jsonb_build_object('release_version','1.22.0','phase','33.9','runs',(select coalesce(jsonb_agg(to_jsonb(x) order by x.run_at desc),'[]'::jsonb) from(select r.id,r.release_version,r.phase,r.status,r.checks,r.run_note,r.run_at,r.approved_at,r.approval_note,coalesce(rb.display_name,'Former staff') run_by_name,coalesce(ab.display_name,'—') approved_by_name from public.internal_release_candidate_runs r left join public.staff_profiles rb on rb.shop_id=r.shop_id and rb.user_id=r.run_by left join public.staff_profiles ab on ab.shop_id=r.shop_id and ab.user_id=r.approved_by where r.shop_id=v_shop order by r.run_at desc limit 20)x));end $$;

alter function public.export_business_backup() rename to export_business_backup_phase338_base;revoke all on function public.export_business_backup_phase338_base() from public;revoke all on function public.export_business_backup_phase338_base() from authenticated;
create or replace function public.export_business_backup() returns jsonb language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_base jsonb;v_export uuid;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;v_base:=public.export_business_backup_phase338_base();v_export:=(v_base->>'export_id')::uuid;update public.backup_exports set schema_version='1.22.0' where id=v_export and shop_id=v_shop;return(v_base-'schema_version')||jsonb_build_object('schema_version','1.22.0','internal_release_candidate_runs',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.internal_release_candidate_runs t where shop_id=v_shop),'internal_release_candidate_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.internal_release_candidate_events t where shop_id=v_shop));end $$;
revoke all on function public.run_internal_release_candidate(text) from public;revoke all on function public.approve_internal_release_candidate(uuid,text) from public;revoke all on function public.get_internal_release_candidate_board() from public;revoke all on function public.export_business_backup() from public;
grant execute on function public.run_internal_release_candidate(text) to authenticated;grant execute on function public.approve_internal_release_candidate(uuid,text) to authenticated;grant execute on function public.get_internal_release_candidate_board() to authenticated;grant execute on function public.export_business_backup() to authenticated;
